-- Spell data from LandSandBoat's spell_list (id, display name, MP cost, cast time in ms,
-- valid target mask, base potency, multiplier, skill, element, client animation id).
-- Casting needs the MP cost and cast time the client also uses, and the animation id is
-- what the client plays when the spell resolves.
CREATE TABLE IF NOT EXISTS spells (
    id           INTEGER PRIMARY KEY,
    name         TEXT    NOT NULL,
    mp           INTEGER NOT NULL DEFAULT 0,
    cast_time    INTEGER NOT NULL DEFAULT 2000,
    valid_targets INTEGER NOT NULL DEFAULT 0,
    base         INTEGER NOT NULL DEFAULT 0,
    multiplier   REAL    NOT NULL DEFAULT 1.0,
    skill        INTEGER NOT NULL DEFAULT 0,
    element      INTEGER NOT NULL DEFAULT 0,
    animation    INTEGER NOT NULL DEFAULT 0
);
DELETE FROM spells;
